/**
 * Music bed + sound effects for «nuven-informativo», generated by code from the
 * cue sheet (scripts/cues.mjs ← content/timings.json ← the real voice), so every
 * tick and whoosh lands on the frame where the picture reacts.
 *
 *   node scripts/music.mjs   →  assets/audio/music.wav + assets/audio/sfx.wav (48 kHz, 16-bit stereo)
 *
 * Original synthesis (no samples, no third-party music): free to use, see
 * content/creditos.md. Ducking under the voice is NOT baked in: the composition
 * carves the bed against the narration (HyperFrames voiceover carve).
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { cues as readCues } from "./cues.mjs";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const { duration: DURATION, scenes, cues: C } = readCues();
const S = Object.fromEntries(scenes.map((s) => [s.id, s]));
const SR = 48000;
const N = Math.ceil(DURATION * SR);

// ───────────────────────── buffers & helpers ─────────────────────────
const bus = () => ({ L: new Float32Array(N), R: new Float32Array(N) });
const music = bus();
const sfx = bus();
// effect sends per stem, so each stem carries its own reverb (mixable separately in Studio)
const sends = new Map([
  [music, { verb: bus(), delay: bus() }],
  [sfx, { verb: bus(), delay: bus() }],
]);
const duck = new Float32Array(N).fill(1); // sidechain gain written by the kick

const clamp = (v, a = 0, b = 1) => Math.min(b, Math.max(a, v));
const lerp = (a, b, t) => a + (b - a) * t;
const smooth = (t) => {
  const x = clamp(t);
  return x * x * (3 - 2 * x);
};
const ramp = (t, a, b) => smooth((t - a) / (b - a));
const mtof = (m) => 440 * 2 ** ((m - 69) / 12);
const idx = (t) => Math.max(0, Math.min(N, Math.round(t * SR)));

let seed = 12345;
const rnd = () => {
  seed = (seed + 0x6d2b79f5) >>> 0;
  let r = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  r = (r + Math.imul(r ^ (r >>> 7), 61 | r)) ^ r;
  return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
};
const noise = () => rnd() * 2 - 1;

/** Equal-power pan, p in [-1, 1]. */
const panGains = (p) => [Math.cos(((p + 1) * Math.PI) / 4), Math.sin(((p + 1) * Math.PI) / 4)];

/** Topology-preserving state-variable filter (Zavalishin). */
class SVF {
  ic1 = 0;
  ic2 = 0;
  run(x, fc, q = 0.707) {
    const g = Math.tan((Math.PI * Math.min(fc, SR * 0.45)) / SR);
    const k = 1 / q;
    const a1 = 1 / (1 + g * (g + k));
    const a2 = g * a1;
    const a3 = g * a2;
    const v3 = x - this.ic2;
    const v1 = a1 * this.ic1 + a2 * v3;
    const v2 = this.ic2 + a2 * this.ic1 + a3 * v3;
    this.ic1 = 2 * v1 - this.ic1;
    this.ic2 = 2 * v2 - this.ic2;
    return { lp: v2, bp: v1, hp: x - k * v1 - v2 };
  }
}

/**
 * Renders a voice from t0 for dur seconds. fn(tl, i) returns a sample (mono)
 * or [l, r]; pan may be a number or a function of tl. send = reverb amount.
 */
function voice(target, t0, dur, fn, { pan = 0, gain = 1, verb = 0, delay = 0, ducked = false } = {}) {
  const a = idx(t0);
  const b = idx(t0 + dur);
  for (let i = a; i < b; i++) {
    const tl = (i - a) / SR;
    let v = fn(tl, i);
    let l, r;
    if (Array.isArray(v)) [l, r] = v;
    else {
      const [gl, gr] = panGains(typeof pan === "function" ? pan(tl) : pan);
      l = v * gl;
      r = v * gr;
    }
    const g = gain * (ducked ? duck[i] : 1);
    l *= g;
    r *= g;
    target.L[i] += l;
    target.R[i] += r;
    const fx = sends.get(target);
    if (verb) {
      fx.verb.L[i] += l * verb;
      fx.verb.R[i] += r * verb;
    }
    if (delay) {
      fx.delay.L[i] += l * delay;
      fx.delay.R[i] += r * delay;
    }
  }
}

/** Band-limited-ish saw (polyBLEP). */
function sawOsc() {
  let ph = rnd();
  return (f) => {
    const dt = f / SR;
    ph += dt;
    if (ph >= 1) ph -= 1;
    let v = 2 * ph - 1;
    if (ph < dt) {
      const t = ph / dt;
      v -= t + t - t * t - 1;
    } else if (ph > 1 - dt) {
      const t = (ph - 1) / dt;
      v -= t * t + t + t + 1;
    }
    return v;
  };
}


// ───────────────────────── score ─────────────────────────
// Calm, minimal electronic: 96 BPM, A minor (Am9 – Fmaj7 – Cmaj7 – G6/9), the same
// harmony as the brand reel so both pieces sound like one identity.
const BEAT = 60 / 96;
const BAR = BEAT * 4;
const GRID0 = 0;
const CHORDS = [
  { bass: 33, pad: [57, 60, 64, 71] },
  { bass: 29, pad: [53, 57, 60, 64] },
  { bass: 36, pad: [55, 60, 64, 71] },
  { bass: 31, pad: [55, 59, 62, 69] },
];
const chordAt = (t) => CHORDS[Math.floor((t - GRID0) / BAR) % 4];
const beats = (a, b) => {
  const out = [];
  for (let n = Math.ceil(a / BEAT - 1e-6); n * BEAT < b - 1e-6; n++) out.push(n * BEAT);
  return out;
};
const END = DURATION;
const BREATH = [C.impressionKey - 0.2, S.aporta.start]; // drums drop out under «tu primera impresión»
const inBreath = (t) => t >= BREATH[0] && t < BREATH[1];
const DRUMS = (t) => t >= S.evolucion.start && t < END - 3.2 && !inBreath(t);
/** intensity per scene (0..1): the bed grows as the argument builds, opens on the promo */
function energy(t) {
  if (t < S.evolucion.start) return 0.35;
  if (t < S.importa.start) return 0.55;
  if (t < S.aporta.start) return inBreath(t) ? 0.45 : 0.65;
  if (t < S.promo.start) return 0.7;
  return 0.85;
}
const padCut = (t) => 500 + 2600 * energy(t) + (inBreath(t) ? 1200 * ramp(t, BREATH[0], BREATH[1]) : 0);
/** master envelope of the bed: fade in, resolve and fade out on the end card */
const bedEnv = (t) => ramp(t, 0, 1.6) * (1 - ramp(t, END - 2.6, END - 0.05));

function kick(t0, amp = 1) {
  voice(music, t0, 0.45, (tl) => {
    const f = 48 + 90 * Math.exp(-tl * 34);
    return Math.tanh(1.3 * Math.sin(2 * Math.PI * f * tl * (1 + 0.5 * Math.exp(-tl * 34)))) * Math.exp(-tl * 8) * amp * bedEnv(t0 + tl);
  }, { gain: 0.5 });
}
function hat(t0, amp = 1, pan = 0.25) {
  const f = new SVF();
  voice(music, t0, 0.07, (tl) => f.run(noise(), 9000, 0.8).hp * Math.exp(-tl * 75) * amp * bedEnv(t0 + tl), { gain: 0.08, pan, verb: 0.05 });
}
function clap(t0, amp = 1) {
  const f = new SVF();
  voice(music, t0, 0.3, (tl) => {
    const env = tl < 0.025 ? Math.exp(-((tl % 0.008) * 450)) : Math.exp(-(tl - 0.02) * 20);
    return f.run(noise(), 1400, 1.1).bp * env * amp * bedEnv(t0 + tl);
  }, { gain: 0.22, verb: 0.3 });
}
function bassNote(t0, dur, midi) {
  const f = new SVF();
  const osc = sawOsc();
  voice(music, t0, dur, (tl) => {
    const fr = mtof(midi);
    const env = Math.min(1, tl / 0.01) * Math.exp(-tl * 1.6);
    const body = Math.sin(2 * Math.PI * fr * tl) * 0.9 + f.run(osc(fr), 260, 0.8).lp * 0.35;
    return Math.tanh(1.2 * body) * env * energy(t0) * bedEnv(t0 + tl);
  }, { gain: 0.32 });
}
function pluck(t0, midi, pan, amp = 1) {
  const f = new SVF();
  const osc = sawOsc();
  voice(music, t0, 0.7, (tl) => {
    const env = Math.min(1, tl / 0.004) * Math.exp(-tl * 6);
    return f.run(osc(mtof(midi)), 700 + 3000 * Math.exp(-tl * 12), 1).lp * env * amp * bedEnv(t0 + tl);
  }, { gain: 0.08, pan, verb: 0.3, delay: 0.25 });
}
function bell(target, t0, midi, { dur = 2, amp = 1, pan = 0, verb = 0.45, bright = 1, gain = 0.12 } = {}) {
  const fc = mtof(midi);
  voice(target, t0, dur, (tl) => {
    const env = Math.min(1, tl / 0.003) * Math.exp(-tl * (4.8 / dur));
    return Math.sin(2 * Math.PI * fc * tl + bright * 2 * Math.exp(-tl * 4) * Math.sin(2 * Math.PI * fc * 3.5 * tl)) * env * amp;
  }, { gain, pan, verb });
}

// pad: continuous, chord per bar, filter follows the argument
{
  const vs = [0, 1, 2, 3].map(() => [sawOsc(), sawOsc()]);
  const fl = [new SVF(), new SVF()];
  let cut = 600;
  voice(music, 0, DURATION, (t) => {
    const env = bedEnv(t);
    if (env <= 0.0001) return [0, 0];
    const notes = t >= END - 3.2 ? [45, 57, 60, 64, 71] : chordAt(t).pad;
    cut += (padCut(t) - cut) * 0.0004;
    let l = 0;
    let r = 0;
    notes.forEach((m, n) => {
      const f = mtof(m);
      l += vs[n % 4][0](f * 0.9968);
      r += vs[n % 4][1](f * 1.0032);
    });
    const breath = 0.88 + 0.12 * Math.sin(t * 1.3);
    return [fl[0].run(l, cut, 0.75).lp * env * breath, fl[1].run(r, cut * 1.03, 0.75).lp * env * breath];
  }, { gain: 0.06, verb: 0.4 });
}
// drums & bass
for (const b of beats(0, END)) {
  const n = Math.round(b / BEAT);
  if (DRUMS(b)) {
    if (n % 2 === 0) kick(b, b >= S.promo.start ? 1 : 0.85);
    hat(b + BEAT / 2, n % 4 === 3 ? 1 : 0.7);
    if (b >= S.importa.start) hat(b + BEAT / 4, 0.35, -0.3);
    if (b >= S.promo.start && n % 4 === 2) clap(b);
  }
  if (n % 2 === 0 && b >= S.evolucion.start - BAR && b < END - 3.2) bassNote(b, BEAT * 1.9, chordAt(b).bass + 12 * (n % 4 === 2 ? 1 : 0));
}
// arpeggio from «por qué importa» on (8ths), brighter in the promo
for (let t = S.importa.start; t < END - 3.4; t += BEAT / 2) {
  if (inBreath(t)) continue;
  const k = Math.round((t - S.importa.start) / (BEAT / 2));
  const pad = chordAt(t).pad;
  pluck(t, pad[[0, 2, 1, 3, 2, 1][k % 6]] + 12, k % 2 ? 0.35 : -0.35, t >= S.promo.start ? 1 : 0.7);
}
// resolution chord under the end card
[57, 64, 69, 72, 76].forEach((m, i) => bell(music, END - 3.1 + i * 0.03, m, { dur: 3, amp: 0.5, pan: (i - 2) * 0.2, verb: 0.6 }));

// ───────────────────────── sound effects (subtle) ─────────────────────────
function whoosh(t0, dur, { from = -0.6, to = 0.6, lo = 300, hi = 4500, amp = 1, q = 1.2 } = {}) {
  const f = new SVF();
  voice(sfx, t0, dur, (tl) => {
    const x = tl / dur;
    return f.run(noise(), lo * (hi / lo) ** smooth(x), q).bp * Math.sin(Math.PI * Math.min(1, x)) ** 1.8 * amp;
  }, { gain: 0.3, pan: (tl) => lerp(from, to, smooth(tl / dur)), verb: 0.15 });
}
function tick(t0, { f = 2800, amp = 1, pan = 0 } = {}) {
  voice(sfx, t0, 0.03, (tl) => (Math.sin(2 * Math.PI * f * tl) * 0.75 + noise() * 0.25) * Math.exp(-tl * 190) * amp, { gain: 0.14, pan, verb: 0.03 });
}
function pop(t0, midi, pan = 0) {
  bell(sfx, t0, midi, { dur: 0.6, amp: 0.8, pan, verb: 0.2, bright: 0.5, gain: 0.1 });
  tick(t0, { f: 1800, amp: 0.6, pan });
}
function swell(t0, dur, amp = 1) {
  const f = new SVF();
  voice(sfx, t0, dur, (tl) => {
    const x = tl / dur;
    return f.run(noise(), 300 + 4000 * x * x, 1.4).bp * x ** 2 * amp;
  }, { gain: 0.25, verb: 0.3 });
}
function thump(t0, amp = 1) {
  voice(sfx, t0, 1.0, (tl) => Math.tanh(1.4 * Math.sin(2 * Math.PI * (46 + 40 * Math.exp(-tl * 20)) * tl)) * Math.exp(-tl * 4) * amp, { gain: 0.35, verb: 0.3 });
}
/** ticks for a count-up from 0 to `to` over `dur` (expo.out like the counter on screen) */
function countTicks(t0, dur, to, step) {
  let last = -1;
  for (let t = t0; t < t0 + dur; t += 1 / 120) {
    const x = (t - t0) / dur;
    const v = Math.floor(((1 - 2 ** (-10 * x)) * to) / step);
    if (v !== last) {
      tick(t, { f: 2600 + (v % 3) * 180, amp: 0.55, pan: 0.1 });
      last = v;
    }
  }
}

// scene transitions: soft whooshes (the N ribbon sweeps)
for (const id of ["evolucion", "fuera", "importa", "aporta"]) whoosh(S[id].start - 0.22, 0.55, { amp: 0.8 });
whoosh(C.toUSA - 0.25, 0.5, { from: 0.6, to: -0.6, amp: 0.7 }); // ribbon wipe España → EE. UU.
// counters
countTicks(C.count64, 1.1, 64, 8);
countTicks(C.count83, 0.9, 83, 8);
pop(C.label12, 81, 0.3);
countTicks(C.ring28, 1.2, 28, 4);
pop(C.line34, 76, -0.2);
countTicks(C.seg37, 1.1, 37, 5);
countTicks(C.count97, 1.1, 97, 10);
pop(C.oneInSix, 76, 0);
// «tu primera impresión»: a breath, then a soft swell into the benefits
swell(C.impressionKey - 0.1, S.aporta.start - C.impressionKey + 0.1, 0.8);
// four benefit icons
C.icons.forEach((t, i) => pop(t, [69, 72, 76, 81][i], (i - 1.5) * 0.3));
// logo: ribbon fold + warm thump, chime on the call to action
whoosh(C.logo, 0.6, { from: -0.4, to: 0.4, lo: 500, hi: 6000, amp: 0.7 });
thump(C.logo + 0.55, 0.9);
bell(sfx, C.logo + 0.55, 69, { dur: 2.2, amp: 0.6, verb: 0.55, gain: 0.1 });
bell(sfx, C.cta, 81, { dur: 1.6, amp: 0.5, verb: 0.5, gain: 0.08 });

// ───────────────────────── effects buses & master ─────────────────────────
/** Ping-pong delay: left line fed by the input, right line by the left (dotted eighth). */
function pingPong(src, dst, time = BEAT * 0.75, fb = 0.38) {
  const d = Math.round(time * SR);
  const L = new Float32Array(N);
  const R = new Float32Array(N);
  for (let i = 0; i < N; i++) {
    const dl = i >= d ? L[i - d] : 0;
    const dr = i >= d ? R[i - d] : 0;
    L[i] = (src.L[i] + src.R[i]) * 0.5 + dr * fb;
    R[i] = dl;
    dst.L[i] += dl * 0.5;
    dst.R[i] += dr * 0.5;
  }
}
function freeverb(src) {
  const s = SR / 44100;
  const combs = [1116, 1188, 1277, 1356, 1422, 1491, 1557, 1617];
  const aps = [556, 441, 341, 225];
  const out = bus();
  for (const [ch, spread] of [
    ["L", 0],
    ["R", 23],
  ]) {
    const x = src[ch];
    const y = out[ch];
    for (const c of combs) {
      const len = Math.round((c + spread) * s);
      const buf = new Float32Array(len);
      let p = 0;
      let store = 0;
      for (let i = 0; i < N; i++) {
        const o = buf[p];
        store = o * 0.75 + store * 0.25; // damping
        buf[p] = x[i] * 0.015 + store * 0.86; // room size
        y[i] += o;
        if (++p >= len) p = 0;
      }
    }
    for (const a of aps) {
      const len = Math.round((a + spread) * s);
      const buf = new Float32Array(len);
      let p = 0;
      for (let i = 0; i < N; i++) {
        const b = buf[p];
        const inp = y[i];
        y[i] = b - inp;
        buf[p] = inp + b * 0.5;
        if (++p >= len) p = 0;
      }
    }
  }
  return out;
}


for (const [stem, fx] of sends) {
  pingPong(fx.delay, stem);
  pingPong(fx.delay, fx.verb);
  const wet = freeverb(fx.verb);
  for (let i = 0; i < N; i++) {
    stem.L[i] += wet.L[i] * 0.9;
    stem.R[i] += wet.R[i] * 0.9;
  }
}
// hard edges: silence at both ends
for (const b of [music, sfx]) {
  const a = idx(0.02);
  const z = idx(DURATION - 0.05);
  for (let i = 0; i < N; i++) {
    const g = i < a ? i / a : i >= z ? Math.max(0, 1 - (i - z) / (N - z)) : 1;
    b.L[i] *= g;
    b.R[i] *= g;
  }
}
// each stem peak-normalised to -6 dBFS; levels are set in the mix (data-volume)
function normalise(b, db = -6) {
  let p = 0;
  for (let i = 0; i < N; i++) p = Math.max(p, Math.abs(b.L[i]), Math.abs(b.R[i]));
  const g = 10 ** (db / 20) / (p || 1);
  for (let i = 0; i < N; i++) {
    b.L[i] *= g;
    b.R[i] *= g;
  }
}
normalise(music);
normalise(sfx);
const soft = (v) => v;
function wav(path, b) {
  const data = Buffer.alloc(N * 4);
  for (let i = 0; i < N; i++) {
    data.writeInt16LE(Math.round(clamp(soft(b.L[i]), -1, 1) * 32767), i * 4);
    data.writeInt16LE(Math.round(clamp(soft(b.R[i]), -1, 1) * 32767), i * 4 + 2);
  }
  const h = Buffer.alloc(44);
  h.write("RIFF", 0);
  h.writeUInt32LE(36 + data.length, 4);
  h.write("WAVE", 8);
  h.write("fmt ", 12);
  h.writeUInt32LE(16, 16);
  h.writeUInt16LE(1, 20);
  h.writeUInt16LE(2, 22);
  h.writeUInt32LE(SR, 24);
  h.writeUInt32LE(SR * 4, 28);
  h.writeUInt16LE(4, 32);
  h.writeUInt16LE(16, 34);
  h.write("data", 36);
  h.writeUInt32LE(data.length, 40);
  writeFileSync(path, Buffer.concat([h, data]));
}


const dir = join(root, "assets/audio");
mkdirSync(dir, { recursive: true });
wav(join(dir, "music.wav"), music);
wav(join(dir, "sfx.wav"), sfx);
console.log(`✓ assets/audio/music.wav + sfx.wav · ${DURATION.toFixed(2)}s`);
